import { describe, expect, it } from 'vitest'
import { PERIODICITY } from '@/modules/chargeConcept/schema'
import {
  isAutoGenerated,
  periodicityCadenceLabel,
  type AutoGeneratable,
} from '@/modules/chargeConcept/helpers/chargeGeneration'

/**
 * Tests for isAutoGenerated and periodicityCadenceLabel.
 * Tras el split concepto→política, isAutoGenerated evalúa la forma AutoGeneratable
 * (la que cumple una política con periodicidad automática).
 */

const makeConcept = (overrides: Partial<AutoGeneratable> = {}): AutoGeneratable => ({
  is_active: true,
  periodicity: { is_automatic: true },
  ...overrides,
})

describe('isAutoGenerated', () => {
  it('returns true when is_automatic=true and is_active=true', () => {
    expect(isAutoGenerated(makeConcept({ periodicity: { is_automatic: true }, is_active: true }))).toBe(true)
  })

  it('returns false when is_automatic=false', () => {
    expect(isAutoGenerated(makeConcept({ periodicity: { is_automatic: false }, is_active: true }))).toBe(false)
  })

  it('returns false when is_automatic=true but is_active=false', () => {
    expect(isAutoGenerated(makeConcept({ periodicity: { is_automatic: true }, is_active: false }))).toBe(false)
  })

  it('returns false when periodicity is undefined', () => {
    expect(isAutoGenerated(makeConcept({ periodicity: undefined }))).toBe(false)
  })

  it('returns false when periodicity is null', () => {
    expect(isAutoGenerated(makeConcept({ periodicity: null }))).toBe(false)
  })

  it('works for any automatic periodicity (is_automatic drives it, not the UUID)', () => {
    expect(isAutoGenerated(makeConcept({ periodicity: { is_automatic: true }, is_active: true }))).toBe(true)
  })
})

describe('periodicityCadenceLabel', () => {
  it('returns "cada mes" for MONTHLY', () => {
    expect(periodicityCadenceLabel(PERIODICITY.MONTHLY)).toBe('cada mes')
  })

  it('returns "cada 2 meses" for BIMONTHLY', () => {
    expect(periodicityCadenceLabel(PERIODICITY.BIMONTHLY)).toBe('cada 2 meses')
  })

  it('returns "cada año" for YEARLY', () => {
    expect(periodicityCadenceLabel(PERIODICITY.YEARLY)).toBe('cada año')
  })

  it('returns "cada semana" for WEEKLY', () => {
    expect(periodicityCadenceLabel(PERIODICITY.WEEKLY)).toBe('cada semana')
  })

  it('returns "cada quincena" for BIWEEKLY', () => {
    expect(periodicityCadenceLabel(PERIODICITY.BIWEEKLY)).toBe('cada quincena')
  })

  it('returns "automáticamente" for unknown periodicity ID', () => {
    expect(periodicityCadenceLabel('unknown-uuid')).toBe('automáticamente')
  })

  it('returns "automáticamente" for undefined', () => {
    expect(periodicityCadenceLabel(undefined)).toBe('automáticamente')
  })

  it('returns "automáticamente" for null', () => {
    expect(periodicityCadenceLabel(null)).toBe('automáticamente')
  })
})
